	g.emit(Instruction{
		Op:    OpLabel,
		Label: endLabel,
	})

	return nil
}

// genReturn generates IR for a return statement
func (g *Generator) genReturn(node *ast.Node) error {
	if len(node.Children) == 0 {
		g.emit(Instruction{Op: OpReturn})
		return nil
	}

	returnOp, err := g.genExpr(node.Children[0])
	if err != nil {
		return err
	}

	g.emit(Instruction{
		Op:   OpReturn,
		Src1: returnOp,
	})

	return nil
