// genExpr generates IR for an expression and returns the operand
func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
	if node == nil {
		return Operand{}, fmt.Errorf("nil expression")
	}

	switch node.Kind {
	case ast.NodeIntLit:
