	// Emit call
	result := g.newTemp()
	g.emit(Instruction{
		Op:   OpCall,
		Dest: result,
		Fn:   fnName,
	})

	return result, nil
}

// Helper functions

func (g *Generator) newTemp() Operand {
	temp := Operand{
		IsTemp: true,
		Name:   fmt.Sprintf("t%d", g.tempCount),
	}
	g.tempCount++
	return temp
}

func (g *Generator) newLabel(prefix string) string {
	label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
	g.labelCount++
	return label
}

func (g *Generator) emit(instr Instruction) {
	if g.currentFn != nil {
		g.currentFn.Body = append(g.currentFn.Body, instr)
	} else {
		g.program.Main = append(g.program.Main, instr)
	}
}

func (g *Generator) opcodeFromOp(op string) Opcode {
	switch op {
	case "+":
		return OpAdd
	case "-":
		return OpSub
	case "*":
		return OpMul
	case "/":
		return OpDiv
	case "==":
		return OpEq
	case "!=":
		return OpNe
	case "<":
		return OpLt
	case ">":
		return OpGt
	case "<=":
		return OpLe
	case ">=":
		return OpGe
