	loopLabel := g.newLabel("loop")
	endLabel := g.newLabel("end")

	// Emit loop label
	g.emit(Instruction{
		Op:    OpLabel,
		Label: loopLabel,
	})

	// Check condition: iterator < end
	cmpTemp := g.newTemp()
	g.emit(Instruction{
		Op:   OpLt,
		Dest: cmpTemp,
		Src1: Operand{Name: iterName},
		Src2: endOp,
	})

	// Jump if false (exit loop)
	g.emit(Instruction{
		Op:    OpJumpIfFalse,
		Src1:  cmpTemp,
		Label: endLabel,
	})

	// Generate body
	if err := g.genStmt(bodyStmt); err != nil {
		return err
	}

	// Increment iterator
	incrTemp := g.newTemp()
	g.emit(Instruction{
		Op:   OpAdd,
		Dest: incrTemp,
		Src1: Operand{Name: iterName},
		Src2: Operand{IsImm: true, ImmVal: 1},
	})
	g.emit(Instruction{
		Op:   OpCopy,
		Dest: Operand{Name: iterName},
		Src1: incrTemp,
	})

	// Jump back to loop
	g.emit(Instruction{
		Op:    OpJump,
		Label: loopLabel,
	})

	// Emit end label
	g.emit(Instruction{
		Op:    OpLabel,
		Label: endLabel,
	})

